var i=`design-by-contract`;var n=10;var a={en:[{id:`T010-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Design by Contract`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`SOLID groups five object-oriented design heuristics: single responsibility, open/closed, Liskov substitution, interface segregation, and dependency inversion.`},{id:`B`,text:`POLA says an interface should behave in ways its users reasonably expect.`},{id:`C`,text:`DRY means every piece of knowledge should have one authoritative representation.`},{id:`D`,text:`Design by Contract specifies preconditions, postconditions, and invariants for components.`}]},{id:`T010-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Design by Contract`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Separate requirements that are committed, plausible, and speculative.`},{id:`B`,text:`Define boundaries around coherent policies and give each a narrow interface.`},{id:`C`,text:`Document valid inputs and states, guarantees on successful return, and properties that must remain true across operations.`},{id:`D`,text:`Prefer asking an object to perform an operation over traversing several objects and making decisions externally.`}]},{id:`T010-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`A wallet transfer requires a positive amount, valid accounts, and an invariant that recorded debit and credit balance.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`Expose a purpose-specific billing profile contract rather than sharing every internal field.`},{id:`B`,text:`Consistent confirmation and audit behavior matter more than clever UI shortcuts.`},{id:`C`,text:`Move the authoritative calculation server-side and expose a stable contract; client-side previews should be treated as provisional, not a competing source of truth.`},{id:`D`,text:`Define what happens on insufficient funds and ensure the operation is atomic.`}]},{id:`T010-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Design by Contract`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Different audiences have different expectations; conventions can evolve.`},{id:`B`,text:`Excessive interfaces, inheritance hierarchies, and dependency-injection plumbing make simple code harder to read.`},{id:`C`,text:`Types cannot express every runtime or cross-record invariant.`},{id:`D`,text:`YAGNI must not excuse missing migrations, observability, backups, or compliance requirements.`}]},{id:`T010-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`A contract describes obligations between caller and implementation, including behavior when assumptions are violated.`}]}]},{id:`T010-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`Type annotations alone guarantee every cross-record business invariant.`}]}]},{id:`T010-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Do not rely on assertions that disappear in production, and avoid overly strict preconditions that make substitutable implementations incompatible.`}]}]},{id:`T010-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Design by Contract`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Design by Contract specifies preconditions, postconditions, and invariants for components.`},{id:`B`,text:`Document valid inputs and states, guarantees on successful return, and properties that must remain true across operations.`},{id:`C`,text:`A contract never needs to define outcomes for invalid input or insufficient funds.`},{id:`D`,text:`A surprising side effect is acceptable if it saves a few lines of documentation.`}]},{id:`T010-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Design by Contract`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Type annotations alone guarantee every cross-record business invariant.`},{id:`B`,text:`Speculative features are more important than hard-to-reverse data decisions.`},{id:`C`,text:`Do not rely on assertions that disappear in production, and avoid overly strict preconditions that make substitutable implementations incompatible.`},{id:`D`,text:`Define what happens on insufficient funds and ensure the operation is atomic.`}]},{id:`T010-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`A wallet transfer requires a positive amount, valid accounts, and an invariant that recorded debit and credit balance.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Review a proposed generic plugin system for an MVP. Remove requirements unsupported by current users, list deferred decisions and document which choices are costly to reverse.`},{id:`B`,text:`Refactor a checkout module with two payment providers. Preserve transaction behavior, add provider contract tests, explain which SOLID principles motivated each extraction, and avoid interfaces that have only one speculative use.`},{id:`C`,text:`Specify transfer preconditions, postconditions, invariant and error cases before generating any implementation. Ask the agent for transaction tests covering rollback and concurrency.`},{id:`D`,text:`Audit a REST API and UI for misleading names and hidden side effects. Propose consistent behavior, write examples of expected error responses, and test retry semantics.`}]},{id:`T010-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`What contract guarantees must remain stable when a database or payment provider changes?`}]}]},{id:`T010-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`A wallet transfer requires a positive amount, valid accounts, and an invariant that recorded debit and credit balance.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Design by Contract`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T010-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`A wallet transfer requires a positive amount, valid accounts, and an invariant that recorded debit and credit balance.`,b:!0},{t:` — propose three checks for `},{t:`Design by Contract`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T010-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`A wallet transfer requires a positive amount, valid accounts, and an invariant that recorded debit and credit balance.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T010-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Design by Contract`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`A wallet transfer requires a positive amount, valid accounts, and an invariant that recorded debit and credit balance.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T010-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Проєктування за контрактом`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`SOLID об’єднує п’ять принципів об’єктного проєктування: єдину відповідальність, відкритість/закритість, підстановку Лісков, розділення інтерфейсів та інверсію залежностей.`},{id:`B`,text:`POLA означає, що інтерфейс має поводитися так, як користувач обґрунтовано очікує.`},{id:`C`,text:`DRY означає, що кожне правило або знання має одне авторитетне представлення.`},{id:`D`,text:`Проєктування за контрактом визначає передумови, післяумови та інваріанти компонентів.`}]},{id:`T010-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Проєктування за контрактом`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Розділяйте підтверджені, ймовірні й суто гіпотетичні вимоги.`},{id:`B`,text:`Проводьте межі навколо узгоджених політик і надавайте вузькі інтерфейси.`},{id:`C`,text:`Документуйте допустимі входи та стани, гарантії успішного завершення й властивості, що зберігаються між операціями.`},{id:`D`,text:`Краще просити об’єкт виконати дію, ніж проходити кілька вкладених об’єктів та ухвалювати рішення ззовні.`}]},{id:`T010-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`Переказ між гаманцями вимагає додатної суми, чинних рахунків та інваріанта збалансованих дебету й кредиту.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Надайте цільовий контракт платіжного профілю замість відкриття всіх внутрішніх полів.`},{id:`B`,text:`Узгоджені підтвердження та аудит важливіші за хитрі UI-скорочення.`},{id:`C`,text:`Перенесіть авторитетний розрахунок на сервер і надайте контракт; попередній розрахунок у клієнті вважайте орієнтовним.`},{id:`D`,text:`Визначте поведінку за браку коштів і забезпечте атомарність операції.`}]},{id:`T010-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Проєктування за контрактом`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Різні аудиторії мають різні очікування, а конвенції змінюються.`},{id:`B`,text:`Надлишок інтерфейсів, ієрархій спадкування та DI-обв’язки ускладнює простий код.`},{id:`C`,text:`Типи не виражають усіх інваріантів виконання чи міжзаписних правил.`},{id:`D`,text:`YAGNI не виправдовує відсутність міграцій, спостережуваності, резервних копій чи обов’язкової відповідності нормам.`}]},{id:`T010-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Контракт описує обов’язки виклику й реалізації, зокрема поведінку в разі порушення припущень.`}]}]},{id:`T010-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Лише анотації типів гарантують усі бізнес-інваріанти між записами.`}]}]},{id:`T010-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Не покладайтеся на assertions, що можуть зникати в production, і не вводьте надто суворі передумови, які ламають підстановку реалізацій.`}]}]},{id:`T010-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Проєктування за контрактом`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Проєктування за контрактом визначає передумови, післяумови та інваріанти компонентів.`},{id:`B`,text:`Документуйте допустимі входи та стани, гарантії успішного завершення й властивості, що зберігаються між операціями.`},{id:`C`,text:`Контракту не потрібно описувати некоректні дані чи недостатні кошти.`},{id:`D`,text:`Неочікуваний побічний ефект прийнятний, якщо він заощаджує кілька рядків документації.`}]},{id:`T010-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Проєктування за контрактом`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Лише анотації типів гарантують усі бізнес-інваріанти між записами.`},{id:`B`,text:`Гіпотетичні можливості важливіші за рішення щодо даних, які важко змінити.`},{id:`C`,text:`Не покладайтеся на assertions, що можуть зникати в production, і не вводьте надто суворі передумови, які ламають підстановку реалізацій.`},{id:`D`,text:`Визначте поведінку за браку коштів і забезпечте атомарність операції.`}]},{id:`T010-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Переказ між гаманцями вимагає додатної суми, чинних рахунків та інваріанта збалансованих дебету й кредиту.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Перегляньте пропозицію універсальної системи плагінів для MVP. Приберіть вимоги без реального попиту, перелічіть відкладені рішення та позначте дорогі для перегляду.`},{id:`B`,text:`Відрефакторіть модуль оформлення з двома платіжними провайдерами. Збережіть поведінку транзакцій, додайте контрактні тести й поясніть кожне виділення через SOLID, не створюючи абстракцій для гіпотетичних сценаріїв.`},{id:`C`,text:`До генерації реалізації опишіть передумови, післяумови, інваріант і помилки переказу. Попросіть агента додати транзакційні тести відкату та конкурентного доступу.`},{id:`D`,text:`Перевірте REST API та UI на оманливі назви й приховані побічні ефекти. Запропонуйте узгоджену поведінку, приклади помилок і тести повторних запитів.`}]},{id:`T010-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Які гарантії контракту мають залишатися сталими при заміні БД або платіжного провайдера?`}]}]},{id:`T010-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Переказ між гаманцями вимагає додатної суми, чинних рахунків та інваріанта збалансованих дебету й кредиту.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Проєктування за контрактом`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T010-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Переказ між гаманцями вимагає додатної суми, чинних рахунків та інваріанта збалансованих дебету й кредиту.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Проєктування за контрактом`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T010-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Переказ між гаманцями вимагає додатної суми, чинних рахунків та інваріанта збалансованих дебету й кредиту.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T010-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Проєктування за контрактом`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Переказ між гаманцями вимагає додатної суми, чинних рахунків та інваріанта збалансованих дебету й кредиту.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var r={slug:i,topicId:10,questions:a};export{r as default,a as questions,i as slug,n as topicId};